#[derive(Clone, Copy, Debug)]
enum EggKeeperDraco131Step {
    Start,
    OnEnable,
    OnDisable,
    OnTouch,
}

fn egg_keeper_draco_13_1_run(ctx: &Ctx, mut step: EggKeeperDraco131Step, args: Vec<Val>) -> Result<Val, Stop> {
    'machine: loop {
        match step {
            EggKeeperDraco131Step::Start => {
                step = EggKeeperDraco131Step::OnEnable;
                continue 'machine;
            }
            EggKeeperDraco131Step::OnEnable => {
                ctx.call(Function::EnableNpc, vec![Val::from("Egg Keeper Draco#13_1")])?;
                return Err(Stop::End);
            }
            EggKeeperDraco131Step::OnDisable => {
                ctx.call(Function::DisableNpc, vec![Val::from("Egg Keeper Draco#13_1")])?;
                return Err(Stop::End);
            }
            EggKeeperDraco131Step::OnTouch => {
                ctx.call(Function::DisableNpc, vec![Val::from("Egg Keeper Draco#13_1")])?;
                ctx.call(
                    Function::Monster,
                    vec![
                        Val::from("nyd_dun02"),
                        Val::from(201),
                        Val::from(157),
                        Val::from("Egg Keeper Draco"),
                        Val::from(2013),
                        Val::from(1),
                        Val::from("Egg Keeper Draco#13_3::OnMyMobDead"),
                    ],
                )?;
                return Err(Stop::End);
            }
        }
    }
}

pub fn egg_keeper_draco_13_1(ctx: &Ctx) -> Script {
    egg_keeper_draco_13_1_run(ctx, EggKeeperDraco131Step::Start, Vec::new()).map(|_| ())
}

