    if ((ctx.var("ep13_2_tre").get()? == 3 && ctx.call(Function::CountItem, vec![Val::from(6076)])? == 1)
        && ctx.call(Function::CountItem, vec![Val::from(6077)])?.number()? < 5)
    {
        ctx.call(Function::NpcSpecialEffect, vec![ctx.constant("EF_COUPLECASTING")?])?;
    }
